-- SAT MASTER · 0031 · Library: books and new link providers
--
-- The Library (/dashboard/library) shelves official practice, free open textbooks, public-domain
-- classics and grammar guides — all as links (nothing is copied).
--   * learning_resources.kind may now be 'book'.
--   * learning_resources.provider may now be 'openstax' (free textbooks) or 'gutenberg' (public domain).
-- The two CHECK constraints are replaced by wider ones (every existing value stays valid).
-- The verified links below are added as DRAFTS; an admin publishes them with "Check and publish
-- drafts" (each link is checked from the server first). Existing rows are not touched.

alter table public.learning_resources drop constraint learning_resources_kind_check;
alter table public.learning_resources add constraint learning_resources_kind_check
  check (kind in ('lesson','video','practice','tool','official_info','article','book'));
alter table public.learning_resources drop constraint learning_resources_provider_check;
alter table public.learning_resources add constraint learning_resources_provider_check
  check (provider in ('sat_master','college_board','khan_academy','desmos','youtube','openstax','gutenberg','other'));

insert into public.learning_resources (provider, provider_name, kind, title, description, url, language, subject_id, domain_id, skill_id, usage_terms, attribution, status, position)
select v.provider, v.provider_name, v.kind, v.title, v.description, v.url, 'en', d.subject_id, k.domain_id, k.id, v.usage_terms, v.attribution, 'draft', v.pos
